import{_ as o,a0 as l,w as s,s as u,ao as a,I as r,a1 as i,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在Linux上使用eCryptFS加密文件和目錄 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上使用eCryptFS加密文件和目錄 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上使用eCryptFS加密文件和目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上使用eCryptFS加密文件和目錄 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141027 How to encrypt files and directories with eCryptFS on Linux","title":"在Linux上使用eCryptFS加密文件和目錄","tag":"201412","desc":""},"relativePath":"201412/20141027 How to encrypt files and directories with eCryptFS on Linux.md","filePath":"[post].md"}'),d={name:"201412/20141027 How to encrypt files and directories with eCryptFS on Linux.md"};function f(y,t,C,m,S,x){const p=l("Link");return s(),u("div",null,[t[26]||(t[26]=a('<h1 id="在linux上使用ecryptfs加密文件和目錄" tabindex="-1">在Linux上使用eCryptFS加密文件和目錄 <a class="header-anchor" href="#在linux上使用ecryptfs加密文件和目錄" aria-label="Permalink to “在Linux上使用eCryptFS加密文件和目錄”">​</a></h1><p>作為罪犯，你需要為自己的身份保密；而作為中情局成員，你同樣也需要為自己的身份保密。但是，你卻不是他們其中的任何一員，你只是不想其他人查探到你的金融數據、家庭照片、尚未出版的手稿，或者記錄着你能發家致富的最初想法的私密筆記。</p><p>我時常聽到有人告訴我“我只是個微不足道的人，沒人會查探我”或者“我沒有什麼東西要隱藏的。”好吧，告訴你我的想法，即便我沒有什麼要隱藏的，或者我也可以公開我帶着狗的孩子的照片，那我也有權利不這麼去做，也有權利來保護我的隱私。</p><h3 id="加密類型" tabindex="-1">加密類型 <a class="header-anchor" href="#加密類型" aria-label="Permalink to “加密類型”">​</a></h3><p>我們主要有兩種加密文件和目錄的方法。一種是文件系統級別的加密，在這種加密中，你可以選擇性地加密某些文件或者目錄（如，/home/alice）。對我而言，這是個十分不錯的方法，你不需要為了啓用或者測試加密而把所有一切重新安裝一遍。然而，文件系統級別的加密也有一些缺點。例如，許多現代應用程序會緩存（部分）文件你硬盤中未加密的部分中，比如交換分區、/tmp和/var文件夾，而這會導致隱私泄漏。</p><p>另外一種方式，就是所謂的全盤加密，這意味着整個磁盤都會被加密（可能除了主引導記錄外）。全盤加密工作在物理磁盤級別，寫入到磁盤的每個比特都會被加密，而從磁盤中讀取的任何東西都會在運行中解密。這會阻止任何潛在的對未加密數據的未經授權的訪問，並且確保整個文件系統中的所有東西都被加密，包括交換分區或任何臨時緩存數據。</p><h3 id="可用的加密工具" tabindex="-1">可用的加密工具 <a class="header-anchor" href="#可用的加密工具" aria-label="Permalink to “可用的加密工具”">​</a></h3><p>在Linux中要實施加密，有幾個可供選擇的工具。在本教程中，我打算介紹其中一個：<strong>eCryptFS</strong>，一個用户空間文件系統加密工具。下面提供了一個Linux上可用的加密工具摘要供您參考。</p><h4 id="文件系統級別加密" tabindex="-1">文件系統級別加密 <a class="header-anchor" href="#文件系統級別加密" aria-label="Permalink to “文件系統級別加密”">​</a></h4>',9)),r("ul",null,[r("li",null,[i(p,{href:"http://www.arg0.net/encfs"},{default:n(()=>[...t[0]||(t[0]=[e("EncFS",-1)])]),_:1}),t[1]||(t[1]=e("：嘗試加密的最簡單方式之一。EncFS工作在基於FUSE的偽文件系統上，所以你只需要創建一個加密文件夾並將它掛載到某個文件夾就可以工作了。",-1))]),r("li",null,[i(p,{href:"http://ecryptfs.org/"},{default:n(()=>[...t[2]||(t[2]=[e("eCryptFS",-1)])]),_:1}),t[3]||(t[3]=e("：一個POSIX兼容的加密文件系統，eCryptFS工作方式和EncFS相同，所以你必須掛載它。",-1))])]),t[27]||(t[27]=r("h4",{id:"磁盤級別加密",tabindex:"-1"},[e("磁盤級別加密 "),r("a",{class:"header-anchor",href:"#磁盤級別加密","aria-label":"Permalink to “磁盤級別加密”"},"​")],-1)),r("ul",null,[r("li",null,[i(p,{href:"http://sourceforge.net/projects/loop-aes/"},{default:n(()=>[...t[4]||(t[4]=[e("Loop-AES",-1)])]),_:1}),t[5]||(t[5]=e("：最古老的磁盤加密方法。它真的很快，並且適用於舊系統（如，2.0內核分支）。",-1))]),r("li",null,[i(p,{href:"https://code.google.com/p/cryptsetup/wiki/DMCrypt"},{default:n(()=>[...t[6]||(t[6]=[e("DMCrypt",-1)])]),_:1}),t[7]||(t[7]=e("：最常見的磁盤加密方案，支持現代Linux內核。",-1))]),r("li",null,[i(p,{href:"https://ciphershed.org/"},{default:n(()=>[...t[8]||(t[8]=[e("CipherShed",-1)])]),_:1}),t[9]||(t[9]=e("：已停止的TrueCrypt磁盤加密程序的一個開源分支。",-1))])]),t[28]||(t[28]=a(`<h3 id="ecryptfs基礎" tabindex="-1">eCryptFS基礎 <a class="header-anchor" href="#ecryptfs基礎" aria-label="Permalink to “eCryptFS基礎”">​</a></h3><p>eCrypFS是一個基於FUSE的用户空間加密文件系統，在Linux內核2.6.19及更高版本中可用（作為encryptfs模組）。eCryptFS加密的偽文件系統是掛載到當前文件系統頂部的。它可以很好地工作在EXT文件系統家族和其它文件系統如JFS、XFS、ReiserFS、Btrfs，甚至是NFS/CIFS共享文件系統上。Ubuntu使用eCryptFS作為加密其家目錄的默認方法，ChromeOS也是。在eCryptFS底層，默認使用的是AES算法，但是它也支持其它算法，如blowfish、des3、cast5、cast6。如果你是通過手工創建eCryptFS設置，你可以選擇其中一種算法。</p><p>就像我所的，Ubuntu讓我們在安裝過程中選擇是否加密/home目錄。好吧，這是使用eCryptFS的最簡單的一種方法。</p><p><img src="https://farm6.staticflickr.com/5600/15639040345_8d74cd54a8_z.jpg" alt=""></p><p>Ubuntu提供了一個用户友好的工具集，通過eCryptFS可以讓我們的生活更輕鬆，但是在Ubuntu安裝過程中啓用eCryptFS只創建了一個指定的預配置的設置。所以，如果默認的設置不適合你的需求，你需要進行手工設置。在本教程中，我將介紹<strong>如何在主流Linux發行版上手工設置eCryptFS</strong>。</p><h3 id="ecryptfs的安裝" tabindex="-1">eCryptFS的安裝 <a class="header-anchor" href="#ecryptfs的安裝" aria-label="Permalink to “eCryptFS的安裝”">​</a></h3><p>Debian，Ubuntu或其衍生版：</p><pre><code>$ sudo apt-get install ecryptfs-utils 
</code></pre><p>注意，如果你在Ubuntu安裝過程中選擇加密家目錄，eCryptFS應該已經安裝了。</p><p>CentOS, RHEL or Fedora：</p><pre><code># yum install ecryptfs-utils
</code></pre><p>Arch Linux：</p><pre><code>$ sudo pacman -S ecryptfs-utils
</code></pre><p>在安裝完包後，加載eCryptFS內核模組當然會是一個很好的實踐：</p><pre><code>$ sudo modprobe ecryptfs
</code></pre><h3 id="配置ecryptfs" tabindex="-1">配置eCryptFS <a class="header-anchor" href="#配置ecryptfs" aria-label="Permalink to “配置eCryptFS”">​</a></h3><p>現在，讓我們開始加密一些目錄，運行eCryptFS配置工具：</p><pre><code>$ ecryptfs-setup-private 
</code></pre><p><img src="https://farm6.staticflickr.com/5608/15453440890_3b4be6d5a7_z.jpg" alt=""></p><p>它會要求你輸入登錄密碼和掛載密碼。登錄密碼和你常規登錄的密碼一樣，而掛載密碼用於派生一個文件加密主密鑰。這裏留空可以生成一個（複雜的），這樣會更安全。登出然後重新登錄。</p><p>你會注意到，eCryptFS默認在你的家目錄中創建了兩個目錄：Private和.Private。~/.Private目錄包含有加密的數據，而你可以在~/Private目錄中訪問到相應的解密後的數據。在你登錄時，~/.Private目錄會自動解密並映射到~/Private目錄，因此你可以訪問它。當你登出時，~/Private目錄會自動卸載，而~/Private目錄中的內容會加密回到~/.Private目錄。</p><p>eCryptFS怎麼會知道你擁有~/.Private目錄，並自動將其解密到~/Private目錄而不需要我們輸入密碼呢？這就是eCryptFS的PAM模組搗的鬼，它為我們提供了這項便利服務。</p><p>如果你不想讓~/Private目錄在登錄時自動掛載，只需要在運行ecryptfs-setup-private工具時添加“--noautomount”選項。同樣，如果你不想要~/Private目錄在登出後自動卸載，也可以自動“--noautoumount”選項。但是，那樣後，你需要自己手工掛載或卸載~/Private目錄：</p><pre><code>$ ecryptfs-mount-private ~/.Private ~/Private
$ ecryptfs-umount-private ~/Private
</code></pre><p>你可以來驗證一下.Private文件夾是否被掛載，運行：</p><pre><code>$ mount 
</code></pre><p><img src="https://farm6.staticflickr.com/5610/15452374739_2ffb73cf05_z.jpg" alt=""></p><p>現在，我們可以開始把任何敏感文件放進~/Private文件夾裏頭了，它們會在我們登出時自動被加密並鎖在~/.Private文件內。</p>`,28)),r("p",null,[t[11]||(t[11]=e("所有這一切看起來是那麼得神奇。這主要是ecryptfs-setup-private工具讓一切設置變得簡單。如果你想要深究一點，對eCryptFS指定的方面進行設置，那麼請轉到",-1)),i(p,{href:"http://ecryptfs.org/documentation.html"},{default:n(()=>[...t[10]||(t[10]=[e("官方文檔",-1)])]),_:1}),t[12]||(t[12]=e("。",-1))]),t[29]||(t[29]=r("h3",{id:"結尾",tabindex:"-1"},[e("結尾 "),r("a",{class:"header-anchor",href:"#結尾","aria-label":"Permalink to “結尾”"},"​")],-1)),t[30]||(t[30]=r("p",null,"綜上所述，如果你十分關注你的隱私，最好是將基於eCryptFS文件系統級別的加密和全盤加密相結合。切記，只進行文件加密並不能保證你的隱私不受侵犯。",-1)),t[31]||(t[31]=r("hr",null,null,-1)),r("p",null,[t[14]||(t[14]=e("via: ",-1)),i(p,{href:"http://xmodulo.com/encrypt-files-directories-ecryptfs-linux.html"},{default:n(()=>[...t[13]||(t[13]=[e("http://xmodulo.com/encrypt-files-directories-ecryptfs-linux.html",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=e("作者：",-1)),i(p,{href:"http://xmodulo.com/author/valerio"},{default:n(()=>[...t[15]||(t[15]=[e("Christopher Valerio",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),i(p,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[16]||(t[16]=[e("GOLinux",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創翻譯，",-1)),i(p,{href:"http://linux.cn/"},{default:n(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const b=o(d,[["render",f]]);export{h as __pageData,b as default};
